// Phase 3 — execute and cache
try { $response = $next($request); } catch (\Throwable $t) { $this->repository->release($scopedKey); throw $t; }
if ($response->getStatusCode() >= 200 && $response->getStatusCode() < 300) {
    $this->repository->complete($scopedKey, $response, $payloadHash, (int) config('idempotency.ttl_seconds', 86400));
} else {
    $this->repository->release($scopedKey);
}
return $response;
